namespace ghidra.framework.store.local;

using static org.junit.Assert;



using org.junit;

using generic.test;
using ghidra.util;

public class LockFileTest : AbstractGenericTest {

	private static readonly File DIRECTORY = new File(AbstractGenericTest.getTestDirectoryPath());
	private static readonly string LOCKNAME = "test";
	private static readonly File LOCKFILE = new File(DIRECTORY, LOCKNAME + ".lock");
	private static readonly int DEFAULT_MAX_LOCK_LEASE_PERIOD_MS = 1500;
	private static readonly int DEFAULT_LOCK_RENEWAL_PERIOD = DEFAULT_MAX_LOCK_LEASE_PERIOD_MS - 200;
	/**
	 * The default timeout for obtaining a lock.
	 */
	private static readonly int DEFAULT_TIMEOUT_MS = 3000;

	/**
	 * Constructor for LockFileTest.
	 * @param arg0
	 */
	public LockFileTest() : base()
    {
	}

	/*
	 * @see TestCase#setUp()
	 */
	/* @Before */
	public void setUp()
    {

		LOCKFILE.delete();
	}

	/*
	 * @see TestCase#tearDown()
	 */
	/* @After */
	public void tearDown()
    {
		LOCKFILE.delete();

	}

	/* @Test */
	public void testLock() {

		LockFile lock1 = new LockFile(DIRECTORY, LOCKNAME, DEFAULT_MAX_LOCK_LEASE_PERIOD_MS,
			DEFAULT_LOCK_RENEWAL_PERIOD, DEFAULT_TIMEOUT_MS);
		LockFile lock2 = new LockFile(DIRECTORY, LOCKNAME, DEFAULT_MAX_LOCK_LEASE_PERIOD_MS,
			DEFAULT_LOCK_RENEWAL_PERIOD, DEFAULT_TIMEOUT_MS);

		Console.WriteLine("Create lock: " + lock1);
		bool rc = lock1.createLock(DEFAULT_TIMEOUT_MS, false);
		assertTrue(rc);

		Console.WriteLine("Create a new lock w/ hold (must wait for old lock to expire)...");
		rc = lock2.createLock(DEFAULT_TIMEOUT_MS, true);
		assertTrue(rc);

		Console.WriteLine("Verify that lock is holding...");
		rc = lock1.createLock(DEFAULT_TIMEOUT_MS, false);
		assertTrue(!rc);

		Console.WriteLine("Verify again that lock is holding...");
		rc = lock1.createLock(DEFAULT_TIMEOUT_MS, false);
		assertTrue(!rc);

		Console.WriteLine("Get second immediate lock...");
		rc = lock2.createLock(0, false);
		assertTrue(rc);

		Console.WriteLine("Remove first lock immediate...");
		lock2.removeLock();
		assertTrue(lock2.haveLock()); // should still have lock
		assertTrue(lock2.haveLock(true));

		Console.WriteLine("Remove second lock...");
		lock2.removeLock();
		assertTrue(!lock2.haveLock()); // should not have lock
		assertTrue(!lock2.haveLock(true));

		Console.WriteLine("Create immediate lock: " + lock1);
		rc = lock1.createLock(0, false);
		assertTrue(rc);

		Msg.error(this, ">>>>>>>>>>>>>>>> Expected Exception");
		lock2.removeLock(); // should have no affect
		Msg.error(this, "<<<<<<<<<<<<<<<< End Expected Exception");
		assertTrue(lock1.haveLock(true));

		Console.WriteLine("Remove lock...");
		lock1.removeLock();
		assertTrue(!lock1.haveLock(true));

	}

}
